{
  "name": "InsurancePolicyId",
  "in": "path",
  "required": true,
  "description": "Unique identifier for a given insurance policy",
  "schema": {
    "$ref": "#/components/schemas/AEInsurance.AEInsuranceResourceIdentifierType"
  }
}

{
  "type": "string",
  "minLength": 1,
